import{_ as u,a0 as a,w as i,s as r,I as n,x as o,a1 as s,A as l,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"修复安装完 Ubuntu 后无可引导设备的错误 | LCTT x X-CMD","titleTemplate":false,"description":"修复安装完 Ubuntu 后无可引导设备的错误 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修复安装完 Ubuntu 后无可引导设备的错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修复安装完 Ubuntu 后无可引导设备的错误 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150824 Fix No Bootable Device Found Error After Installing Ubuntu","title":"修复安装完 Ubuntu 后无可引导设备的错误","tag":"201509","desc":""},"relativePath":"201509/20150824 Fix No Bootable Device Found Error After Installing Ubuntu.md","filePath":"[post].md"}'),d={name:"201509/20150824 Fix No Bootable Device Found Error After Installing Ubuntu.md"};function b(f,t,m,g,h,U){const e=a("Link");return i(),r("div",null,[t[20]||(t[20]=n("h1",{id:"修复安装完-ubuntu-后无可引导设备的错误",tabindex:"-1"},[o("修复安装完 Ubuntu 后无可引导设备的错误 "),n("a",{class:"header-anchor",href:"#修复安装完-ubuntu-后无可引导设备的错误","aria-label":"Permalink to “修复安装完 Ubuntu 后无可引导设备的错误”"},"​")],-1)),t[21]||(t[21]=n("p",null,[o("通常情况下，我会安装启动 Ubuntu 和 Windows 的双系统，但是这次我决定完全消除 Windows 纯净安装 Ubuntu。纯净安装 Ubuntu 完成后，结束时屏幕输出 "),n("strong",null,"无可引导设备(no bootable device found)"),o(" 而不是进入 GRUB 界面。显然，安装搞砸了 UEFI 引导设置。")],-1)),t[22]||(t[22]=n("p",null,[n("img",{src:"http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/08/No_Bootable_Device_Found_1.jpg",alt:"安装完 Ubuntu 后无可引导设备"})],-1)),t[23]||(t[23]=n("p",null,[o("我会告诉你我是如何修复"),n("strong",null,"在宏碁笔记本上安装 Ubuntu 后出现无可引导设备错误"),o("的。我声明了我使用的是宏碁灵越 R13，这很重要，因为我们需要更改固件设置，而这些设置可能因制造商和设备有所不同。")],-1)),t[24]||(t[24]=n("p",null,"因此在你开始这里介绍的步骤之前，先看一下发生这个错误时我计算机的状态：",-1)),n("ul",null,[t[2]||(t[2]=n("li",null,"我的宏碁灵越 R13 预装了 Windows 8.1 和 UEFI 引导管理器",-1)),n("li",null,[t[1]||(t[1]=o("安全引导（ Secure boot）没有关闭，（我的笔记本刚维修过，维修人员又启用了它，直到出现了问题我才发现）。你可以阅读这篇博文了解",-1)),s(e,{href:"http://itsfoss.com/disable-secure-boot-in-acer/"},{default:l(()=>[...t[0]||(t[0]=[o("如何在宏碁笔记本中关闭安全引导（secure boot）",-1)])]),_:1})]),t[3]||(t[3]=n("li",null,"我选择了清除所有东西安装 Ubuntu，例如现有的 Windows 8.1，各种分区等",-1)),t[4]||(t[4]=n("li",null,"安装完 Ubuntu 之后，从硬盘启动时我看到无可引导设备错误。但能从 USB 设备正常启动",-1))]),t[25]||(t[25]=n("p",null,"在我看来，没有禁用安全引导（secure boot）可能是这个错误的原因。但是，我没有数据支撑我的观点。这仅仅是预感。有趣的是，双系统启动 Windows 和 Linux 经常会出现这两个 Grub 问题：",-1)),n("ul",null,[n("li",null,[s(e,{href:"http://itsfoss.com/solve-error-partition-grub-rescue-ubuntu-linux/"},{default:l(()=>[...t[5]||(t[5]=[o("错误：没有 grub 救援分区",-1)])]),_:1})]),n("li",null,[s(e,{href:"http://itsfoss.com/fix-minimal-bash-line-editing-supported-grub-error-linux/"},{default:l(()=>[...t[6]||(t[6]=[o("支持最小化 BASH 式的行编辑",-1)])]),_:1})])]),t[26]||(t[26]=p('<p>如果你遇到类似的情况，你可以试试我的修复方法。</p><h3 id="修复安装完-ubuntu-后无可引导设备错误" tabindex="-1">修复安装完 Ubuntu 后无可引导设备错误 <a class="header-anchor" href="#修复安装完-ubuntu-后无可引导设备错误" aria-label="Permalink to “修复安装完 Ubuntu 后无可引导设备错误”">​</a></h3><p>请原谅我的图片质量很差。我的一加相机不能很好地拍摄笔记本屏幕。</p><h4 id="第一步" tabindex="-1">第一步 <a class="header-anchor" href="#第一步" aria-label="Permalink to “第一步”">​</a></h4><p>关闭电源并进入引导设置。我需要在宏碁灵越 R13 上快速地按下 Fn+F2。如果你使用固态硬盘的话要按的非常快，因为固态硬盘启动速度很快。这取决于你的制造商，你可能要用 Del 或 F10 或者 F12。</p><h4 id="第二步" tabindex="-1">第二步 <a class="header-anchor" href="#第二步" aria-label="Permalink to “第二步”">​</a></h4><p>在引导设置中，确保启用了 Secure Boot。它在 Boot 标签里。</p><h4 id="第三步" tabindex="-1">第三步 <a class="header-anchor" href="#第三步" aria-label="Permalink to “第三步”">​</a></h4><p>进入到 Security 标签，找到 “选择一个用于执行的可信任 UEFI 文件（Select an UEFI file as trusted for executing）” 并敲击回车。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/08/No_Bootable_Device_Found_2.jpg" alt="修复无可引导设备错误"></p><p>特意说明，我们这一步是要在你的设备中添加 UEFI 设置文件（安装 Ubuntu 的时候生成）到可信 UEFI 启动中。如果你记得的话，UEFI 启动的主要目的是提供安全性，由于（可能）没有禁用安全引导（Secure Boot），设备不会试图从新安装的操作系统中启动。添加它到类似白名单的可信列表，会使设备从 Ubuntu UEFI 文件启动。</p><h4 id="第四步" tabindex="-1">第四步 <a class="header-anchor" href="#第四步" aria-label="Permalink to “第四步”">​</a></h4><p>在这里你可以看到你的硬盘，例如 HDD0。如果你有多块硬盘，我希望你记住你安装 Ubuntu 的那块。同样敲击回车。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/08/No_Bootable_Device_Found_3.jpg" alt="在 Boot 设置中修复无可引导设备错误"></p><h4 id="第五步" tabindex="-1">第五步 <a class="header-anchor" href="#第五步" aria-label="Permalink to “第五步”">​</a></h4><p>你应该可以看到 &lt;EFI&gt; 了，敲击回车。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/08/No_Bootable_Device_Found_4.jpg" alt="在 UEFI 中修复设置"></p><h4 id="第六步" tabindex="-1">第六步 <a class="header-anchor" href="#第六步" aria-label="Permalink to “第六步”">​</a></h4><p>在下一个屏幕中你会看到 &lt;Ubuntu&gt;。耐心点，马上就好了。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/08/No_Bootable_Device_Found_5.jpg" alt="安装完 Ubuntu 后修复启动错误"></p><h4 id="第七步" tabindex="-1">第七步 <a class="header-anchor" href="#第七步" aria-label="Permalink to “第七步”">​</a></h4><p>你可以看到 shimx64.efi，grubx64.efi 和 MokManager.efi 文件。重要的是 shimx64.efi。选中它并敲击回车。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/08/No_Bootable_Device_Found_6.jpg" alt="修复无可引导设备"></p><p>在下一个屏幕中，输入 Yes 并敲击回车。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/08/No_Bootable_Device_Found_7.jpg" alt="无可引导设备_7"></p><h4 id="第八步" tabindex="-1">第八步 <a class="header-anchor" href="#第八步" aria-label="Permalink to “第八步”">​</a></h4><p>当我们添加它到可信 EFI 文件并执行后，按 F10 保存并退出。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/08/No_Bootable_Device_Found_8.jpg" alt="保存并退出固件设置"></p><p>重启你的系统，这时你就可以看到熟悉的 GRUB 界面了。就算你没有看到 Grub 界面，起码也再也不会看到“无可引导设备”。你应该可以进入 Ubuntu 了。</p><p>如果修复后搞乱了你的 Grub 界面，但你确实能登录系统，你可以重装 Grub 并进入到 Ubuntu 熟悉的紫色 Grub 界面。</p><p>我希望这篇指南能帮助你修复无可引导设备错误。欢迎提出任何疑问、建议或者感谢。</p><hr>',32)),n("p",null,[t[8]||(t[8]=o("via: ",-1)),s(e,{href:"http://itsfoss.com/no-bootable-device-found-ubuntu/"},{default:l(()=>[...t[7]||(t[7]=[o("http://itsfoss.com/no-bootable-device-found-ubuntu/",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=o("作者：",-1)),s(e,{href:"http://itsfoss.com/author/abhishek/"},{default:l(()=>[...t[9]||(t[9]=[o("Abhishek",-1)])]),_:1}),t[13]||(t[13]=o(" 译者：",-1)),s(e,{href:"http://www.mutouxiaogui.cn/blog/"},{default:l(()=>[...t[10]||(t[10]=[o("ictlyh",-1)])]),_:1}),t[14]||(t[14]=o(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[11]||(t[11]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=o("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[15]||(t[15]=[o("LCTT",-1)])]),_:1}),t[18]||(t[18]=o(" 原创翻译，",-1)),s(e,{href:"https://linux.cn/"},{default:l(()=>[...t[16]||(t[16]=[o("Linux中国",-1)])]),_:1}),t[19]||(t[19]=o(" 荣誉推出",-1))])])}const T=u(d,[["render",b]]);export{B as __pageData,T as default};
